-- Günün sorusu havuzu: zor sorular (supabase/sorular.py ile üretildi, elle düzenlemeyin)
delete from public.quiz_questions;

-- Bugünün sorusu yenilendi: bugünkü cevaplar sıfırlanır, herkese haber verilir
delete from public.quiz_answers where day = public.quiz_day();
  select array_agg(user_id), 'Günün sorusu yenilendi 🧠', 'Bugüne özel çok zor yeni soru geldi · 30 saniyen var', './#soru', 'soru-' || public.quiz_day() || '-2', false
    from public.members where status = 'active' group by group_id;
